348→// StartSession starts an interactive session and registers it for pane
349→// capture in artifacts. Returns nil if the agent does not support interactive
350→// mode. The session is closed automatically during test cleanup.
351→func (s *RepoState) StartSession(t *testing.T, ctx context.Context) agents.Session {
352→	t.Helper()
353→	session, err := s.Agent.StartSession(ctx, s.Dir)
354→	if err != nil {
355→		t.Fatalf("start session: %v", err)
356→	}
357→	if session == nil {
358→		return nil
359→	}
360→	s.session = session
361→	return session
362→}
