449→// NewCheckpointCommits returns the SHAs of commits added to the
450→// entire/checkpoints/v1 branch since the test was set up, oldest first.
451→func NewCheckpointCommits(t *testing.T, s *RepoState) []string {
452→	t.Helper()
453→
454→	log := GitOutput(t, s.Dir, "log", "--reverse", "--format=%H", s.CheckpointBefore+"..entire/checkpoints/v1")
455→	if log == "" {
456→		return nil
457→	}
458→	return strings.Split(log, "\n")
459→}
