461→// CheckpointIDs lists all checkpoint IDs from the tree at the tip of the
462→// checkpoint branch. It parses the two-level directory structure
463→// ({prefix}/{suffix}/metadata.json) and returns the concatenated IDs.
464→func CheckpointIDs(t *testing.T, dir string) []string {
465→	t.Helper()
466→	out := gitOutputSafe(dir, "ls-tree", "-r", "--name-only", "entire/checkpoints/v1")
467→	if out == "" {
468→		return nil
469→	}
470→	seen := map[string]bool{}
471→	var ids []string
472→	for _, line := range strings.Split(strings.TrimSpace(out), "\n") {
473→		// Match {prefix}/{suffix}/metadata.json (top-level, not session-level)
474→		parts := strings.Split(line, "/")
475→		if len(parts) == 3 && parts[2] == "metadata.json" {
476→			id := parts[0] + parts[1]
477→			if !seen[id] {
478→				seen[id] = true
479→				ids = append(ids, id)
480→			}
481→		}
482→	}
483→	return ids
484→}
