530→	blob := "entire/checkpoints/v1:" + path
531→
532→	deadline := time.Now().Add(timeout)
533→	for time.Now().Before(deadline) {
534→		raw := gitOutputSafe(dir, "show", blob)
535→		if raw != "" {
536→			var meta SessionMetadata
537→			if err := json.Unmarshal([]byte(raw), &meta); err != nil {
538→				t.Fatalf("unmarshal session metadata from %s: %v", blob, err)
539→			}
540→			return meta
541→		}
542→		time.Sleep(500 * time.Millisecond)
543→	}
544→	t.Fatalf("session metadata %s did not appear within %s", blob, timeout)
545→	return SessionMetadata{}
