548→// SetupBareRemote creates a bare git repo, adds it as "origin", and pushes
549→// the initial commit. Returns the bare repo path.
550→func SetupBareRemote(t *testing.T, s *RepoState) string {
551→	t.Helper()
552→
553→	var bareDir string
554→	if os.Getenv("E2E_KEEP_REPOS") != "" {
555→		var err error
556→		bareDir, err = os.MkdirTemp("", "e2e-bare-*")
557→		if err != nil {
558→			t.Fatalf("create bare remote dir: %v", err)
559→		}
560→		t.Logf("E2E_KEEP_REPOS: bare remote will be preserved at %s", bareDir)
561→	} else {
562→		bareDir = t.TempDir()
563→	}
564→
565→	Git(t, bareDir, "init", "--bare")
566→	Git(t, s.Dir, "remote", "add", "origin", bareDir)
567→	Git(t, s.Dir, "push", "-u", "origin", "HEAD")
568→	return bareDir
569→}
