571→// GitOutputErr runs a git command and returns (output, error) without
572→// failing the test. For commands expected to fail.
573→func GitOutputErr(dir string, args ...string) (string, error) {
574→	cmd := exec.Command("git", args...)
575→	if dir != "" {
576→		cmd.Dir = dir
