 28→func newResumeCmd() *cobra.Command {
 29→	var force bool
 30→
 31→	cmd := &cobra.Command{
 32→		Use:   "resume <branch>",
 33→		Short: "Switch to a branch and resume its session",
 34→		Long: `Switch to a local branch and resume the agent session from its last commit.
 35→
 36→This command:
 37→1. Checks out the specified branch
 38→2. Finds the session ID from commits unique to this branch (not on main)
 39→3. Restores the session log if it doesn't exist locally
 40→4. Shows the command to resume the session
 41→
 42→If the branch doesn't exist locally but exists on origin, you'll be prompted
 43→to fetch it.
 44→
 45→If newer commits without checkpoints exist on the branch (e.g., after merging main
 46→or cherry-picking from elsewhere), this operation will reset your Git status to the
 47→most recent commit with a checkpoint.  You'll be prompted to confirm resuming in this case.`,
 48→		Args: cobra.ExactArgs(1),
 49→		RunE: func(cmd *cobra.Command, args []string) error {
 50→			if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
 51→				return nil
 52→			}
 53→			return runResume(cmd.Context(), args[0], force)
 54→		},
 55→	}
 56→
 57→	cmd.Flags().BoolVarP(&force, "force", "f", false, "Resume from older checkpoint without confirmation")
 58→
 59→	return cmd
 60→}
 61→
 62→func runResume(ctx context.Context, branchName string, force bool) error {
 63→	// Check if we're already on this branch
 64→	currentBranch, err := GetCurrentBranch(ctx)
 65→	if err == nil && currentBranch == branchName {
 66→		// Already on the branch, skip checkout
 67→		return resumeFromCurrentBranch(ctx, branchName, force)
 68→	}
 69→
 70→	// Check if branch exists locally
 71→	exists, err := BranchExistsLocally(ctx, branchName)
 72→	if err != nil {
 73→		return fmt.Errorf("failed to check branch: %w", err)
 74→	}
 75→
 76→	if !exists {
 77→		// Branch doesn't exist locally, check if it exists on remote
 78→		remoteExists, err := BranchExistsOnRemote(ctx, branchName)
 79→		if err != nil {
 80→			return fmt.Errorf("failed to check remote branch: %w", err)
 81→		}
 82→
 83→		if !remoteExists {
 84→			return fmt.Errorf("branch '%s' not found locally or on origin", branchName)
 85→		}
 86→
 87→		// Ask user if they want to fetch from remote
 88→		shouldFetch, err := promptFetchFromRemote(branchName)
 89→		if err != nil {
 90→			return err
 91→		}
 92→		if !shouldFetch {
 93→			return nil
 94→		}
 95→
 96→		// Fetch and checkout the remote branch
 97→		fmt.Fprintf(os.Stderr, "Fetching branch '%s' from origin...\n", branchName)
 98→		if err := FetchAndCheckoutRemoteBranch(ctx, branchName); err != nil {
 99→			fmt.Fprintf(os.Stderr, "Failed to checkout branch: %v\n", err)
100→			return NewSilentError(errors.New("failed to checkout branch"))
101→		}
102→		fmt.Fprintf(os.Stderr, "Switched to branch '%s'\n", branchName)
103→	} else {
104→		// Branch exists locally, check for uncommitted changes before checkout
105→		hasChanges, err := HasUncommittedChanges(ctx)
106→		if err != nil {
107→			return fmt.Errorf("failed to check for uncommitted changes: %w", err)
108→		}
109→		if hasChanges {
110→			return errors.New("you have uncommitted changes. Please commit or stash them first")
111→		}
112→
113→		// Checkout the branch
114→		if err := CheckoutBranch(ctx, branchName); err != nil {
115→			fmt.Fprintf(os.Stderr, "Failed to checkout branch: %v\n", err)
116→			return NewSilentError(errors.New("failed to checkout branch"))
117→		}
118→		fmt.Fprintf(os.Stderr, "Switched to branch '%s'\n", branchName)
119→	}
120→
121→	return resumeFromCurrentBranch(ctx, branchName, force)
122→}
123→
124→func resumeFromCurrentBranch(ctx context.Context, branchName string, force bool) error {
125→	repo, err := openRepository(ctx)
126→	if err != nil {
127→		return fmt.Errorf("not a git repository: %w", err)
128→	}
129→
130→	// Find a commit with an Entire-Checkpoint trailer, looking at branch-only commits
131→	result, err := findBranchCheckpoints(repo, branchName)
132→	if err != nil {
133→		return err
134→	}
135→	if len(result.checkpointIDs) == 0 {
136→		fmt.Fprintf(os.Stderr, "No Entire checkpoint found on branch '%s'\n", branchName)
137→		return nil
138→	}
139→
140→	// If there are newer commits without checkpoints, ask for confirmation.
141→	// Merge commits (e.g., from merging main) don't count as "work" and are skipped silently.
142→	if result.newerCommitsExist && !force {
143→		fmt.Fprintf(os.Stderr, "Found checkpoint in an older commit.\n")
144→		fmt.Fprintf(os.Stderr, "There are %d newer commit(s) on this branch without checkpoints.\n", result.newerCommitCount)
145→		fmt.Fprintf(os.Stderr, "Checkpoint from: %s %s\n\n", result.commitHash[:7], firstLine(result.commitMessage))
146→
147→		shouldResume, err := promptResumeFromOlderCheckpoint()
148→		if err != nil {
149→			return err
150→		}
151→		if !shouldResume {
152→			fmt.Fprintf(os.Stderr, "Resume cancelled.\n")
153→			return nil
154→		}
155→	}
156→
157→	// Multiple checkpoints (squash merge): restore all sessions
158→	if len(result.checkpointIDs) > 1 {
159→		return resumeMultipleCheckpoints(ctx, repo, result.checkpointIDs, force)
160→	}
161→
162→	// Single checkpoint: existing behavior (unchanged)
163→	checkpointID := result.checkpointIDs[0]
164→
165→	// Get metadata branch tree for lookups
166→	metadataTree, err := strategy.GetMetadataBranchTree(repo)
167→	if err != nil {
168→		// No local metadata branch, check if remote has it
169→		return checkRemoteMetadata(ctx, repo, checkpointID)
170→	}
171→
172→	// Look up metadata from sharded path
173→	metadata, err := strategy.ReadCheckpointMetadata(metadataTree, checkpointID.Path())
174→	if err != nil {
175→		// Checkpoint exists in commit but no local metadata - check remote
176→		return checkRemoteMetadata(ctx, repo, checkpointID)
177→	}
178→
179→	return resumeSession(ctx, metadata.SessionID, checkpointID, force)
180→}
181→
182→// resumeMultipleCheckpoints restores sessions from multiple checkpoint IDs.
183→// This handles squash merge commits where multiple Entire-Checkpoint trailers
184→// are present in a single commit message. Each checkpoint is looked up independently
185→// and missing metadata is skipped (best-effort).
186→func resumeMultipleCheckpoints(ctx context.Context, repo *git.Repository, checkpointIDs []id.CheckpointID, force bool) error {
187→	logCtx := logging.WithComponent(ctx, "resume")
188→
189→	// Get metadata branch tree (try local first, then remote)
190→	metadataTree, err := strategy.GetMetadataBranchTree(repo)
191→	if err != nil {
192→		// Try fetching from remote
193→		logging.Debug(logCtx, "metadata branch not available locally, trying remote")
194→		if fetchErr := FetchMetadataBranch(ctx); fetchErr != nil {
195→			// If fetch also fails, try remote tree directly
196→			remoteTree, remoteErr := strategy.GetRemoteMetadataBranchTree(repo)
197→			if remoteErr != nil {
198→				fmt.Fprintf(os.Stderr, "Checkpoint metadata not available locally or on remote\n")
199→				return nil //nolint:nilerr // Informational message, not a fatal error
200→			}
201→			metadataTree = remoteTree
202→		} else {
203→			metadataTree, err = strategy.GetMetadataBranchTree(repo)
204→			if err != nil {
205→				fmt.Fprintf(os.Stderr, "Checkpoint metadata not available after fetch\n")
206→				return nil //nolint:nilerr // Informational message, not a fatal error
207→			}
208→		}
209→	}
210→
211→	// Read metadata for all checkpoints and sort by CreatedAt ascending
212→	// (oldest first → newest writes last and wins on disk)
213→	checkpoints := collectCheckpointsByAge(metadataTree, checkpointIDs)
214→
215→	// Iterate sorted checkpoints and restore
216→	strat := GetStrategy(ctx)
217→	var allSessions []strategy.RestoredSession
218→
219→	for _, cp := range checkpoints {
220→		point := strategy.RewindPoint{
221→			IsLogsOnly:   true,
222→			CheckpointID: cp.CheckpointID,
223→			Agent:        cp.Agent,
224→		}
225→
226→		sessions, restoreErr := strat.RestoreLogsOnly(ctx, point, force)
227→		if restoreErr != nil {
228→			logging.Debug(logCtx, "skipping checkpoint: restore failed",
229→				slog.String("checkpoint_id", cp.CheckpointID.String()),
230→				slog.String("error", restoreErr.Error()),
231→			)
232→			continue
233→		}
234→		if len(sessions) == 0 {
235→			logging.Debug(logCtx, "skipping checkpoint: no sessions restored",
236→				slog.String("checkpoint_id", cp.CheckpointID.String()),
237→			)
238→			continue
239→		}
240→
241→		allSessions = deduplicateSessions(allSessions, sessions)
242→	}
243→
244→	if len(allSessions) == 0 {
245→		fmt.Fprintf(os.Stderr, "No session metadata found for checkpoints in this commit\n")
246→		return nil
247→	}
248→
249→	logging.Debug(logCtx, "resume multiple checkpoints completed",
250→		slog.Int("checkpoint_count", len(checkpointIDs)),
251→		slog.Int("session_count", len(allSessions)),
252→	)
253→
254→	return displayRestoredSessions(allSessions)
255→}
256→
257→// collectCheckpointsByAge reads metadata for each checkpoint ID from the tree,
258→// skips any that can't be read, and returns them sorted by CreatedAt ascending.
259→// Sorting ensures the newest checkpoint is restored last and wins on disk,
260→// regardless of trailer order in the commit message.
261→func collectCheckpointsByAge(tree *object.Tree, checkpointIDs []id.CheckpointID) []*strategy.CheckpointInfo {
262→	var checkpoints []*strategy.CheckpointInfo
263→	for _, cpID := range checkpointIDs {
264→		metadata, err := strategy.ReadCheckpointMetadata(tree, cpID.Path())
265→		if err != nil {
266→			continue
267→		}
268→		checkpoints = append(checkpoints, metadata)
269→	}
270→	sort.Slice(checkpoints, func(i, j int) bool {
271→		return checkpoints[i].CreatedAt.Before(checkpoints[j].CreatedAt)
272→	})
273→	return checkpoints
274→}
275→
276→// deduplicateSessions merges new sessions into existing, keeping the one with the latest
277→// CreatedAt when a SessionID appears more than once. This handles squash merges where the
278→// same session may be referenced by multiple checkpoints.
279→func deduplicateSessions(existing, incoming []strategy.RestoredSession) []strategy.RestoredSession {
280→	type entry struct {
281→		index     int
282→		createdAt time.Time
283→	}
284→
285→	seen := make(map[string]entry, len(existing))
286→	for i, s := range existing {
287→		seen[s.SessionID] = entry{index: i, createdAt: s.CreatedAt}
288→	}
289→
290→	for _, sess := range incoming {
291→		if prev, exists := seen[sess.SessionID]; exists {
292→			// Keep the one with the later CreatedAt (more complete transcript)
293→			if sess.CreatedAt.After(prev.createdAt) {
294→				existing[prev.index] = sess
295→				seen[sess.SessionID] = entry{index: prev.index, createdAt: sess.CreatedAt}
296→			}
297→		} else {
298→			seen[sess.SessionID] = entry{index: len(existing), createdAt: sess.CreatedAt}
299→			existing = append(existing, sess)
300→		}
301→	}
302→
303→	return existing
304→}
305→
306→// branchCheckpointsResult contains the result of searching for checkpoints on a branch.
307→type branchCheckpointsResult struct {
308→	checkpointIDs     []id.CheckpointID
309→	commitHash        string
310→	commitMessage     string
311→	newerCommitsExist bool // true if there are branch-only commits (not merge commits) without checkpoints
312→	newerCommitCount  int  // count of branch-only commits without checkpoints
313→}
314→
315→// findBranchCheckpoints finds the most recent commit with an Entire-Checkpoint trailer
316→// among commits that are unique to this branch (not reachable from the default branch).
317→// This handles the case where main has been merged into the feature branch.
318→func findBranchCheckpoints(repo *git.Repository, branchName string) (*branchCheckpointsResult, error) {
319→	result := &branchCheckpointsResult{}
320→
321→	// Get HEAD commit
322→	head, err := repo.Head()
323→	if err != nil {
324→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
325→	}
326→
327→	headCommit, err := repo.CommitObject(head.Hash())
328→	if err != nil {
329→		return nil, fmt.Errorf("failed to get HEAD commit: %w", err)
330→	}
331→
332→	// First, check if HEAD itself has a checkpoint (most common case)
333→	if cpIDs := trailers.ParseAllCheckpoints(headCommit.Message); len(cpIDs) > 0 {
334→		result.checkpointIDs = cpIDs
335→		result.commitHash = head.Hash().String()
336→		result.commitMessage = headCommit.Message
337→		result.newerCommitsExist = false
338→		return result, nil
339→	}
340→
341→	// HEAD doesn't have a checkpoint - find branch-only commits
342→	// Get the default branch name
343→	defaultBranch := getDefaultBranchFromRemote(repo)
344→	if defaultBranch == "" {
345→		// Fallback: try common names
346→		for _, name := range []string{"main", "master"} {
347→			if _, err := repo.Reference(plumbing.NewBranchReferenceName(name), true); err == nil {
348→				defaultBranch = name
349→				break
350→			}
351→		}
352→	}
353→
354→	// If we can't find a default branch, or we're on it, just walk all commits
355→	if defaultBranch == "" || defaultBranch == branchName {
356→		return findCheckpointInHistory(headCommit, nil), nil
357→	}
358→
359→	// Get the default branch reference
360→	defaultRef, err := repo.Reference(plumbing.NewBranchReferenceName(defaultBranch), true)
361→	if err != nil {
362→		// Default branch doesn't exist locally, fall back to walking all commits
363→		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
364→	}
365→
366→	defaultCommit, err := repo.CommitObject(defaultRef.Hash())
367→	if err != nil {
368→		// Can't get default commit, fall back to walking all commits
369→		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
370→	}
371→
372→	// Find merge base
373→	mergeBase, err := headCommit.MergeBase(defaultCommit)
374→	if err != nil || len(mergeBase) == 0 {
375→		// No common ancestor, fall back to walking all commits
376→		return findCheckpointInHistory(headCommit, nil), nil //nolint:nilerr // Intentional fallback
377→	}
378→
379→	// Walk from HEAD to merge base, looking for checkpoint
380→	return findCheckpointInHistory(headCommit, &mergeBase[0].Hash), nil
381→}
382→
383→// findCheckpointInHistory walks commit history from start looking for a checkpoint trailer.
384→// If stopAt is provided, stops when reaching that commit (exclusive).
385→// Returns the first checkpoint found and info about commits between HEAD and the checkpoint.
386→// It distinguishes between merge commits (bringing in other branches) and regular commits
387→// (actual branch work) to avoid false warnings after merging main.
388→func findCheckpointInHistory(start *object.Commit, stopAt *plumbing.Hash) *branchCheckpointsResult {
389→	result := &branchCheckpointsResult{}
390→	branchWorkCommits := 0 // Regular commits without checkpoints (actual work)
391→	const maxCommits = 100 // Limit search depth
392→	totalChecked := 0
393→
394→	current := start
395→	for current != nil && totalChecked < maxCommits {
396→		// Stop if we've reached the boundary
397→		if stopAt != nil && current.Hash == *stopAt {
398→			break
399→		}
400→
401→		// Check for checkpoint trailer
402→		if cpIDs := trailers.ParseAllCheckpoints(current.Message); len(cpIDs) > 0 {
403→			result.checkpointIDs = cpIDs
404→			result.commitHash = current.Hash.String()
405→			result.commitMessage = current.Message
406→			// Only warn about branch work commits, not merge commits
407→			result.newerCommitsExist = branchWorkCommits > 0
408→			result.newerCommitCount = branchWorkCommits
409→			return result
410→		}
411→
412→		// Only count regular commits (not merge commits) as "branch work"
413→		if current.NumParents() <= 1 {
414→			branchWorkCommits++
415→		}
416→
417→		totalChecked++
418→
419→		// Move to parent (first parent for merge commits - follows the main line)
420→		if current.NumParents() == 0 {
421→			break
422→		}
423→		parent, err := current.Parent(0)
424→		if err != nil {
425→			// Can't get parent, treat as end of history
426→			break
427→		}
428→		current = parent
429→	}
430→
431→	// No checkpoint found
432→	return result
433→}
434→
435→// promptResumeFromOlderCheckpoint asks the user if they want to resume from an older checkpoint.
436→func promptResumeFromOlderCheckpoint() (bool, error) {
437→	var confirmed bool
438→
439→	form := NewAccessibleForm(
440→		huh.NewGroup(
441→			huh.NewConfirm().
442→				Title("Resume from this older checkpoint?").
443→				Value(&confirmed),
444→		),
445→	)
446→
447→	if err := form.Run(); err != nil {
448→		if errors.Is(err, huh.ErrUserAborted) {
449→			return false, nil
450→		}
451→		return false, fmt.Errorf("failed to get confirmation: %w", err)
452→	}
453→
454→	return confirmed, nil
455→}
