457→// checkRemoteMetadata checks if checkpoint metadata exists on origin/entire/checkpoints/v1
458→// and automatically fetches it if available.
459→func checkRemoteMetadata(ctx context.Context, repo *git.Repository, checkpointID id.CheckpointID) error {
460→	// Try to get remote metadata branch tree
461→	remoteTree, err := strategy.GetRemoteMetadataBranchTree(repo)
462→	if err != nil {
463→		fmt.Fprintf(os.Stderr, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
464→		fmt.Fprintf(os.Stderr, "The entire/checkpoints/v1 branch may not exist locally or on the remote.\n")
465→		return nil //nolint:nilerr // Informational message, not a fatal error
466→	}
467→
468→	// Check if the checkpoint exists on the remote
469→	metadata, err := strategy.ReadCheckpointMetadata(remoteTree, checkpointID.Path())
470→	if err != nil {
471→		fmt.Fprintf(os.Stderr, "Checkpoint '%s' found in commit but session metadata not available\n", checkpointID)
472→		return nil //nolint:nilerr // Informational message, not a fatal error
473→	}
474→
475→	// Metadata exists on remote but not locally - fetch it automatically
476→	fmt.Fprintf(os.Stderr, "Fetching session metadata from origin...\n")
477→	if err := FetchMetadataBranch(ctx); err != nil {
478→		fmt.Fprintf(os.Stderr, "Failed to fetch metadata: %v\n", err)
479→		fmt.Fprintf(os.Stderr, "You can try manually: git fetch origin entire/checkpoints/v1:entire/checkpoints/v1\n")
480→		return NewSilentError(errors.New("failed to fetch metadata"))
481→	}
482→
483→	// Now resume the session with the fetched metadata
484→	return resumeSession(ctx, metadata.SessionID, checkpointID, false)
485→}
486→
487→// resumeSession restores and displays the resume command for a specific session.
488→// For multi-session checkpoints, restores ALL sessions and shows commands for each.
489→// If force is false, prompts for confirmation when local logs have newer timestamps.
490→func resumeSession(ctx context.Context, sessionID string, checkpointID id.CheckpointID, force bool) error {
491→	// Read checkpoint metadata first to get agent type (matching rewind pattern)
492→	repo, err := openRepository(ctx)
493→	if err != nil {
494→		return fmt.Errorf("failed to open repository: %w", err)
495→	}
496→
497→	metadataTree, err := strategy.GetMetadataBranchTree(repo)
498→	if err != nil {
499→		return fmt.Errorf("failed to get metadata branch: %w", err)
500→	}
501→
502→	metadata, err := strategy.ReadCheckpointMetadata(metadataTree, checkpointID.Path())
503→	if err != nil {
504→		return fmt.Errorf("failed to read checkpoint metadata: %w", err)
505→	}
506→
507→	// Resolve agent from checkpoint metadata (same as rewind)
508→	ag, err := strategy.ResolveAgentForRewind(metadata.Agent)
509→	if err != nil {
510→		return fmt.Errorf("failed to resolve agent: %w", err)
511→	}
512→
513→	// Initialize logging context with agent
514→	logCtx := logging.WithAgent(logging.WithComponent(ctx, "resume"), ag.Name())
515→
516→	logging.Debug(logCtx, "resume session started",
517→		slog.String("checkpoint_id", checkpointID.String()),
518→		slog.String("session_id", sessionID),
519→	)
520→
521→	// Get worktree root for session directory lookup
522→	repoRoot, err := paths.WorktreeRoot(ctx)
523→	if err != nil {
524→		return fmt.Errorf("failed to get worktree root: %w", err)
525→	}
526→
527→	sessionDir, err := ag.GetSessionDir(repoRoot)
528→	if err != nil {
529→		return fmt.Errorf("failed to determine session directory: %w", err)
530→	}
531→
532→	// Create directory if it doesn't exist
533→	if err := os.MkdirAll(sessionDir, 0o700); err != nil {
534→		return fmt.Errorf("failed to create session directory: %w", err)
535→	}
536→
537→	// Get strategy and restore sessions using full checkpoint data
538→	strat := GetStrategy(ctx)
539→
540→	// Use RestoreLogsOnly via LogsOnlyRestorer interface for multi-session support
541→	// Create a logs-only rewind point with Agent populated (same as rewind)
542→	point := strategy.RewindPoint{
543→		IsLogsOnly:   true,
544→		CheckpointID: checkpointID,
545→		Agent:        metadata.Agent,
546→	}
547→
548→	sessions, restoreErr := strat.RestoreLogsOnly(ctx, point, force)
549→	if restoreErr != nil || len(sessions) == 0 {
550→		// Fall back to single-session restore (e.g., old checkpoints without agent metadata)
551→		return resumeSingleSession(ctx, ag, sessionID, checkpointID, repoRoot, force)
552→	}
553→
554→	logging.Debug(logCtx, "resume session completed",
555→		slog.String("checkpoint_id", checkpointID.String()),
556→		slog.Int("session_count", len(sessions)),
557→	)
558→
559→	return displayRestoredSessions(sessions)
560→}
561→
562→// displayRestoredSessions sorts sessions by CreatedAt and prints resume commands.
563→// Used by both resumeSession (single checkpoint) and resumeMultipleCheckpoints (squash merge).
564→func displayRestoredSessions(sessions []strategy.RestoredSession) error {
565→	sort.SliceStable(sessions, func(i, j int) bool {
566→		return sessions[i].CreatedAt.Before(sessions[j].CreatedAt)
567→	})
568→
569→	if len(sessions) > 1 {
570→		fmt.Fprintf(os.Stderr, "\nRestored %d sessions. To continue, run:\n", len(sessions))
571→	} else if len(sessions) == 1 {
572→		fmt.Fprintf(os.Stderr, "Session: %s\n", sessions[0].SessionID)
573→		fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
574→	}
575→
576→	for i, sess := range sessions {
577→		sessionAgent, err := strategy.ResolveAgentForRewind(sess.Agent)
578→		if err != nil {
579→			return fmt.Errorf("failed to resolve agent for session %s: %w", sess.SessionID, err)
580→		}
581→		cmd := sessionAgent.FormatResumeCommand(sess.SessionID)
582→
583→		isLast := i == len(sessions)-1
584→		switch {
585→		case len(sessions) > 1 && isLast && sess.Prompt != "":
586→			fmt.Fprintf(os.Stderr, "  %s  # %s (most recent)\n", cmd, sess.Prompt)
587→		case len(sessions) > 1 && isLast:
588→			fmt.Fprintf(os.Stderr, "  %s  # (most recent)\n", cmd)
589→		case sess.Prompt != "":
590→			fmt.Fprintf(os.Stderr, "  %s  # %s\n", cmd, sess.Prompt)
591→		default:
592→			fmt.Fprintf(os.Stderr, "  %s\n", cmd)
593→		}
594→	}
595→
596→	return nil
597→}
598→
599→// resumeSingleSession restores a single session (fallback when multi-session restore fails).
600→// Always overwrites existing session logs to ensure consistency with checkpoint state.
601→// If force is false, prompts for confirmation when local log has newer timestamps.
602→func resumeSingleSession(ctx context.Context, ag agent.Agent, sessionID string, checkpointID id.CheckpointID, repoRoot string, force bool) error {
603→	sessionLogPath, err := resolveTranscriptPath(ctx, sessionID, ag)
604→	if err != nil {
605→		return fmt.Errorf("failed to resolve transcript path: %w", err)
606→	}
607→
608→	if checkpointID.IsEmpty() {
609→		logging.Debug(ctx, "resume session: empty checkpoint ID",
610→			slog.String("checkpoint_id", checkpointID.String()),
611→		)
612→		fmt.Fprintf(os.Stderr, "Session '%s' found in commit trailer but session log not available\n", sessionID)
613→		fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
614→		fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(sessionID))
615→		return nil
616→	}
617→
618→	logContent, _, err := checkpoint.LookupSessionLog(ctx, checkpointID)
619→	if err != nil {
620→		if errors.Is(err, checkpoint.ErrCheckpointNotFound) || errors.Is(err, checkpoint.ErrNoTranscript) {
621→			logging.Debug(ctx, "resume session completed (no metadata)",
622→				slog.String("checkpoint_id", checkpointID.String()),
623→				slog.String("session_id", sessionID),
624→			)
625→			fmt.Fprintf(os.Stderr, "Session '%s' found in commit trailer but session log not available\n", sessionID)
626→			fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
627→			fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(sessionID))
628→			return nil
629→		}
630→		logging.Error(ctx, "resume session failed",
631→			slog.String("checkpoint_id", checkpointID.String()),
632→			slog.String("session_id", sessionID),
633→			slog.String("error", err.Error()),
634→		)
635→		return fmt.Errorf("failed to get session log: %w", err)
636→	}
637→
638→	// Check if local file has newer timestamps than checkpoint
639→	if !force {
640→		localTime := paths.GetLastTimestampFromFile(sessionLogPath)
641→		checkpointTime := paths.GetLastTimestampFromBytes(logContent)
642→		status := strategy.ClassifyTimestamps(localTime, checkpointTime)
643→
644→		if status == strategy.StatusLocalNewer {
645→			sessions := []strategy.SessionRestoreInfo{{
646→				SessionID:      sessionID,
647→				Status:         status,
648→				LocalTime:      localTime,
649→				CheckpointTime: checkpointTime,
650→			}}
651→			shouldOverwrite, promptErr := strategy.PromptOverwriteNewerLogs(sessions)
652→			if promptErr != nil {
653→				return fmt.Errorf("failed to get confirmation: %w", promptErr)
654→			}
655→			if !shouldOverwrite {
656→				fmt.Fprintf(os.Stderr, "Resume cancelled. Local session log preserved.\n")
657→				return nil
658→			}
659→		}
660→	}
661→
662→	// Ensure parent directory exists
663→	if err := os.MkdirAll(filepath.Dir(sessionLogPath), 0o750); err != nil {
664→		return fmt.Errorf("failed to create session directory: %w", err)
665→	}
666→
667→	agentSession := &agent.AgentSession{
668→		SessionID:  sessionID,
669→		AgentName:  ag.Name(),
670→		RepoPath:   repoRoot,
671→		SessionRef: sessionLogPath,
672→		NativeData: logContent,
673→	}
674→
675→	// Write the session using the agent's WriteSession method
676→	if err := ag.WriteSession(ctx, agentSession); err != nil {
677→		logging.Error(ctx, "resume session failed during write",
678→			slog.String("checkpoint_id", checkpointID.String()),
679→			slog.String("session_id", sessionID),
680→			slog.String("error", err.Error()),
681→		)
682→		return fmt.Errorf("failed to write session: %w", err)
683→	}
684→
685→	logging.Debug(ctx, "resume session completed",
686→		slog.String("checkpoint_id", checkpointID.String()),
687→		slog.String("session_id", sessionID),
688→	)
689→
690→	fmt.Fprintf(os.Stderr, "Session restored to: %s\n", sessionLogPath)
691→	fmt.Fprintf(os.Stderr, "Session: %s\n", sessionID)
692→	fmt.Fprintf(os.Stderr, "\nTo continue this session, run:\n")
693→	fmt.Fprintf(os.Stderr, "  %s\n", ag.FormatResumeCommand(sessionID))
694→
695→	return nil
696→}
697→
